/// <summary>
/// CB624_TMSEngineSOCreation
/// Class to proceede with the creation/cancellation process for TMS engine
/// </summary>
abstract class METTMSEngineOrderProccess
{
    METTMSEngineHeaderContract headerContract;

    boolean             isOrderPerishable;
    boolean             isToteCustomer;
    InventParameters    inventParameters;
    TransDate           shippingDate;
    METTMSShipmentID    shipmentId;
    InventLocation      inventLocation;
    METInventLocation   metInventLocation;
    boolean             shipmentCreated;

    TransDate           deliveryDate;
    boolean             hasCCR;

    METTMSShipmentItemGroupHelper TSIGHelper;
    METTMSEngineOrderProccessLinesTmp  proccessLinesTmp;
    str postingIdentifier = '';

}

Method.Source:
/// <summary>
/// Retrive the document header from reference tables
/// </summary>
/// <param name = "_sourceRecord">The record buffer of origin process</param>
/// <param name = "_postingIdentifier">Additional shipment posting identifier</param>
/// <returns>Record buffer of source document header</returns>
private Common getDocumentRecord(Common _sourceRecord, str _postingIdentifier = METConstants::emptyString)
{
    Common ret;

    postingIdentifier = _postingIdentifier;

    if (_sourceRecord is SalesTable || _sourceRecord is InventTransferTable)
    {
        ret = _sourceRecord;
    }
    else if (_sourceRecord is WMSPickingRoute)
    {
        WMSPickingRoute pickingRoute = _sourceRecord;

        postingIdentifier = postingIdentifier == '' ? pickingRoute.pickingRouteID : postingIdentifier;

        if (pickingRoute.transType == InventTransType::Sales)
        {
            ret = SalesTable::find(pickingRoute.transRefId);
        }
        else
        {
            ret = InventTransferTable::find(pickingRoute.transRefId);
        }
    }

    return ret;
}

/// <summary>
/// Gets the shipment Id. Implemented in the child classes
/// </summary>
/// <returns>Shipment Id</returns>
protected METTMSShipmentID getShipmentId()
{
    return METConstants::emptyString;
}

/// <summary>
/// Parameter to get and set posting identifier
/// </summary>
/// <param name = "_postingIdentifier">Additional posting identifier</param>
/// <returns>Posting identifier</returns>
protected str parmPostingIdentifier(str _postingIdentifier = postingIdentifier)
{
    postingIdentifier = _postingIdentifier;

    return postingIdentifier;
}

/// <summary>
/// Initialize the process from shipment data. This method will be extended in the child classes as needed
/// </summary>
/// <param name = "_salesOrderShipmentLoadHeader">Shipment record buffer</param>
public void initFromShipmentData(METSalesOrderShipmentLoadHeader _salesOrderShipmentLoadHeader)
{
    //Method will be implemented/extended in the extension classes.
    if(!inventParameters)
    {
        inventParameters = InventParameters::find();
    }
}

/// <summary>
/// Construct and return the process class instance
/// </summary>
/// <param name = "_executionMode">Type of process stage/source</param>
/// <param name = "_sourceRecord">Source document to be processed</param>
/// <param name = "_postingIdentifier">Additional shipment posting identifier</param>
/// <returns>Instance of class <c>METTMSEngineOrderProccess</c></returns>
public static METTMSEngineOrderProccess construct(METTMSEngineExecutionMode _executionMode, Common _sourceRecord, str _postingIdentifier = '')
{
    METTMSEngineExecutionModeAttribute attribute = new METTMSEngineExecutionModeAttribute(_executionMode);

    METTMSEngineOrderProccess processor = SysExtensionAppClassFactory::getClassFromSysAttribute(classStr(METTMSEngineOrderProccess), attribute) as METTMSEngineOrderProccess;

    if(_sourceRecord is METSalesOrderShipmentLoadHeader)
    {
        processor.initFromShipmentData(_sourceRecord);
    }
    else
    {
        processor.parmPostingIdentifier(_postingIdentifier);
        processor.init(_sourceRecord);
    }

    return processor;
}

/// <summary>
/// main method
/// </summary>
/// <param name = "_args">args</param>
public static void main(Args _args)
{
    METTMSEngineExecutionMode executionMode;

    if (_args.record())
    {
        executionMode = _args.parmEnum();

        METTMSEngineOrderProccess process = METTMSEngineOrderProccess::construct(executionMode, _args.record());

        process.run();

        if (executionMode != METTMSEngineExecutionMode::SalesOrderCancellation || executionMode != METTMSEngineExecutionMode::TransferOrderCancellation)
        {
            info(process.headerContract.showInfo(process.isShipmentCreated()));
        }
    }
    else
    {
        throw error(strfmt("@SYS29104", funcname())); // Class %1 must be called with a buffer.
    }
}

private METTMSSourceDocumentType getDocumentType(METTMSSourceRecordHeaderMap _sourceRecord)
{
    METTMSSourceDocumentType ret;

    if (_sourceRecord.TableId == tableNum(SalesTable))
    {
        ret = METTMSSourceDocumentType::SalesOrderDocument;
    }
    else if (_sourceRecord.TableId == tableNum(InventTransferTable))
    {
        ret = METTMSSourceDocumentType::TransferOrderDocument;
    }

    return ret;
}

/// <summary>
/// initialize default parameters and variables
/// </summary>
/// <param name = "_sourceRecord">source table record buffer</param>
protected void init(Common _sourceRecord)
{
    inventParameters = InventParameters::find();
    Common docRecord = this.getDocumentRecord(_sourceRecord);

    headerContract = METTMSEngineHeaderContract::construct(this.getDocumentType(docRecord), docRecord, this.getShipmentId(), this.parmPostingIdentifier());

    isOrderPerishable = this.isOrderPerishable();

    metInventLocation = METInventLocation::findByInventLocationId(headerContract.parmSourceRecord().InventLocationFrom);
    inventLocation = InventLocation::find(headerContract.parmSourceRecord().InventLocationFrom);
    isToteCustomer = CustTable::METIsToteCustomer(headerContract.getCustomerAccount(), headerContract.parmSourceRecord().DataAreaId);

    shipmentId = headerContract.getShipmentID();

    // initialise shipping and delivery date variables
    shippingDate = this.shippingDate();
    deliveryDate = this.deliveryDate();        
}

/// <summary>
/// Check if the order is perishable
/// </summary>
/// <returns>true, if the order is perishable, otherwise false</returns>
private boolean isOrderPerishable()
{
    return inventParameters.METPerishableOrderSplitGroup && inventParameters.METPerishableOrderSplitGroup == headerContract.getOrderSplitGroup();
}

/// <summary>
/// Validate TMS engine in On on the warehouse
/// </summary>
/// <returns>
/// a boolean value<c>boolean</c> query.
/// </returns>
boolean useTMSEngine()
{
    return metInventLocation.IsTMSEngineUsed;
}

/// <summary>
/// Validate if Perishable SOs are excluded from TMS
/// </summary>
/// <returns>
/// a boolean value<c>boolean</c> query.
/// </returns>
boolean excludePerishable()
{
    return metInventLocation.ExcludePerishables;
}

/// <summary>
/// Refactored new validate method
/// </summary>
/// <returns>true if valdidation successful; otherwise, false.</returns>
protected boolean validate()
{
    //Step 1: check if order should be excluded from TMS Engine processing
    boolean ret = false;

    boolean res = this.validateOrderExcluded();

    if (!res &&
        headerContract.getCarrierCode() &&
        headerContract.getRoute() &&
        this.useTMSEngine() &&
        (!isOrderPerishable ||
        (isOrderPerishable  && !this.excludePerishable())))
    {
        ret = true;
    }

    return ret;
}

/// <summary>
/// Validate the orders to be excluded.
/// </summary>
/// <returns> true if valdidation successful; otherwise, false </returns>
protected boolean validateOrderExcluded()
{
    return headerContract.isOrderExcluded();
}

/// <summary>
/// New method to retrieve the METTMSShipmentOrderTable
/// For creation, straight forward with sales order number
/// Overridden in child classes for packing slip
/// </summary>
/// <param name = "_orderId">Sales order number</param>
/// <param name = "_forUpdate">Select record for update</param>
/// <returns><t>METTMSShipmentOrderTable</t> record found or empty.</returns>
protected METTMSShipmentOrderTable getTMSShipmentOrderTable(str _orderId, boolean _forUpdate = false)
{
    return METTMSShipmentOrderTable::findByOrder(_orderId, this.parmPostingIdentifier(), _forUpdate);
}

/// <summary>
/// Run the TMS engine
/// </summary>
public void run()
{
    METTMSShipmentTable         tmsShipmentTable;
    METTMSShipmentTable         tmsShipmentTableCancel;
    METTMSShipmentOrderTable    tmsShipmentOrderTable;

    //Step 1: check if order should be excluded from TMS Engine processing
    if (this.validate())
    {
        this.initTmpTable();

        try
        {
            ttsbegin;

            tmsShipmentOrderTable   = this.getTMSShipmentOrderTable(headerContract.parmSourceRecord().OrderId);
            //Step 2: Check if the order is already on a shipment
            if (!tmsShipmentOrderTable.RecId)
            {
                //Step 3: If order is not on any existing shipment
                //tmsShipmentTable = this.initTMSShipment(sourceRecord.InventLocationFrom, customerAccount, route, shippingDate);
                tmsShipmentTable = this.initTMSShipment();
                //Step 3a: check if there is an existing shipment this order can be made part of.
                if (!tmsShipmentTable.RecId)
                {
                    this.createShipment();
                }
                else
                {
                    //Step 3c: If a shipment exists, update it
                    this.createShipment(false);
                }
            }
            else
            {
                tmsShipmentTable = this.initTMSShipment();
                //Step 4: If order is on an existing shipment and there is a change to either Route or Ship date
                if (tmsShipmentOrderTable.ShipmentId != shipmentId)
                {
                    //Step 4a: Get the “TMS Shipment” record related to the “TMS Shipment Order”
                    tmsShipmentTableCancel = METTMSShipmentTable::find(tmsShipmentOrderTable.ShipmentId);

                    //Step 4c: Update the current “TMS Shipment” - cancel it
                    this.cancelShipment(headerContract.parmSourceRecord().OrderId);

                    //Step 4d: Link the sales order to a new or existing shipment
                    this.createShipment(!tmsShipmentTable);

                }
                else
                {
                    //Step 5: If order is on an existing shipment and there is no change to both Route and Ship date
                    //delete Shipment itemgroup - recreate                        

                    METTMSShipmentItemGroup tmsItemGroup;

                    delete_from tmsItemGroup
                        exists join tmsShipmentOrderTable
                        where tmsItemGroup.TMSShipmentOrderIdentifier == tmsShipmentOrderTable.TMSShipmentOrderIdentifier
                        && tmsShipmentOrderTable.ShipmentId == shipmentId
                        && tmsShipmentOrderTable.OrderNumber == headerContract.parmSourceRecord().OrderId;

                    delete_from tmsShipmentOrderTable
                        where tmsShipmentOrderTable.ShipmentId  == shipmentId
                        // CB626_TMSEngineSOPackingSlip There could be multiple orders in the same shipment
                    && tmsShipmentOrderTable.OrderNumber == headerContract.parmSourceRecord().OrderId;
                    //Step 3d: Create TMS Shipment Order record
                    //Step 4d: Link the sales order to a new shipment
                    this.createShipment(false);
                }
            }

            //Step 6: Update order and shipment totals
            //Step 6a: Update the order’s “Order weight”
            //Step 6b: Update the order’s “Order volume”
            //Step 6c: Update order’s “Pallet Total footprint”
            this.updateTMSShipmentOrder();

            //Step 6d: Update the shipment’s “Pallet lifts”
            this.updateTMSShipment(shipmentId);

            ttscommit;
        }
        catch (Exception::Error)
        {
            //An error occurs during the creation or updates of the staging records
            error(this.errorMessage());
        }
    }
}

/// <summary>
/// Create an instance of <c>METTMSEngineLinesTmpBuilder</c>
/// </summary>
/// <param name = "_tmsEngineProcess">METTMSEngineSalesOrderProcess enum</param>
/// <param name = "_sourcerRecord"><c>SalesTable</c> record</param>
/// <returns>New instance of <c>METTMSEngineLinesTmpBuilder</c></returns>
METTMSEngineLinesTmpBuilder getTmpBuilderInstance()
{
    return METTMSEngineLinesTmpBuilder::construct(this.getExecutionMode(), headerContract, this.getShipmentId(), this.parmPostingIdentifier());
}

abstract METTMSEngineExecutionMode getExecutionMode()
{

}

/// <summary>
/// Initialise temporary table with calculations
/// </summary>
void initTmpTable()
{
    METTMSEngineLinesTmpBuilder tmpBuilder = this.getTmpBuilderInstance();

    proccessLinesTmp = tmpBuilder.populateTmpTable();
    hasCCR = tmpBuilder.hasCCR();
}

/// <summary>
/// cancel TMS shipment
/// </summary>
/// <param name = "_salesId">SalesId</param>
void cancelShipment(SalesId _salesId)
{
    METTMSShipmentTable         tmsShipmentTable;
    METTMSShipmentOrderTable    tMSShipmentOrderTable;
    METTMSShipmentOrderTable    tMSShipmentOrderTableExist;

    ttsbegin;
    tMSShipmentOrderTable = this.getTMSShipmentOrderTable(headerContract.parmSourceRecord().OrderId, true);

    if (tMSShipmentOrderTable.RecId)
    {
        METTMSShipmentItemGroup tmsItemGroup;

        delete_from tmsItemGroup
            where tmsItemGroup.TMSShipmentOrderIdentifier == tMSShipmentOrderTable.TMSShipmentOrderIdentifier;

        tMSShipmentOrderTable.delete();

        tMSShipmentTable = METTMSShipmentTable::find(tMSShipmentOrderTable.ShipmentId, true);
        // to update the PalletLifts after removing the TSO, excluding delivery note number
        // Do not need to recalc actuals for the original shipment as it's not confirmed yet
        this.updateTMSShipment(tMSShipmentTable.shipmentId, false);

        select firstonly RecId from tMSShipmentOrderTableExist
                    where tMSShipmentOrderTableExist.ShipmentId == tMSShipmentTable.ShipmentID
                    && tMSShipmentOrderTableExist.RecId != tMSShipmentOrderTable.RecId;

        if (!tMSShipmentOrderTableExist.RecId)
        {
            tMSShipmentTable = METTMSShipmentTable::find(tMSShipmentOrderTable.ShipmentId, true);
            tMSShipmentTable.ShipmentStatus = METCashShipmentStatus::Cancelled;

            tMSShipmentTable.update();
        }
    }

    ttscommit;
}

/// <summary>
/// Return if shipment created/updated
/// </summary>
/// <returns>
/// a boolean value<c>boolean</c> query.
/// </returns>
private boolean isShipmentCreated()
{
    return shipmentCreated;
}

/// <summary>
/// create tms shipment tables
/// </summary>
/// <param name = "_isCreateTMSShipment">boolean</param>
protected void createShipment(boolean _isCreateTMSShipment = true)
{
    METTMSShipmentOrderTable    tmsShipmentOrderTable;

    //Step 3b: If no shipment exists, create a new one
    if (_isCreateTMSShipment)
    {
        this.createTMSShipment();
    }
    //Step 3d: Create TMS Shipment Order record
    tmsShipmentOrderTable = this.createTMSShipmentOrder();

    //Step 3e: Create TMS Shipment Item Group records
    // CB626_TMSEngineSOPackingSlip refactoring TSIG record creation
    //this.createTMSShipmentItemGroup(tmsShipmentOrderTable.TMSShipmentOrderIdentifier);
    shipmentCreated = this.createTMSShipmentItemGroup(proccessLinesTmp, tmsShipmentOrderTable.TMSShipmentOrderIdentifier, isToteCustomer, headerContract.parmSourceRecord().InventLocationFrom, hasCCR);
}

/// <summary>
/// Create an instance of <c>METTMSShipmentItemGroupHelper</c>
/// </summary>
/// <param name = "_processLinesTmp">Temporary TMS calculation table</param>
/// <param name = "_tmsShipmentOrderIdentifier">TSO identifier</param>
/// <param name = "_isToteCustomer">Customer uses totes</param>
/// <param name = "_headerInventLocationId">Header warehouse</param>
/// <param name = "_hasCCR">If any of the lines on the SO have a warehouse with SuppWhsHasCCR = Yes</param>
/// <returns>New instance of <c>METTMSShipmentItemGroupHelper</c></returns>
METTMSShipmentItemGroupHelper getTSIGHelperInstance(METTMSEngineOrderProccessLinesTmp _processLinesTmp, METTMSShipmentOrderIdentifier _tmsShipmentOrderIdentifier, boolean _isToteCustomer, InventLocationId _headerInventLocationId, boolean _hasCCR)
{
    return METTMSShipmentItemGroupHelper::construct(_processLinesTmp,
                                                    _tmsShipmentOrderIdentifier,
                                                    _isToteCustomer,
                                                    _headerInventLocationId,
                                                    _hasCCR);
}

/// <summary>
/// Create TSIG record
/// </summary>
/// <param name = "_processLinesTmp">Temporary TMS calculation table</param>
/// <param name = "_tmsShipmentOrderIdentifier">TSO identifier</param>
/// <param name = "_isToteCustomer">Customer uses totes</param>
/// <param name = "_headerInventLocationId">Header warehouse</param>
/// <param name = "_hasCCR">If any of the lines on the SO have a warehouse with SuppWhsHasCCR = Yes</param>
/// <returns>True if creation successful; otherwise, false.</returns>
protected boolean createTMSShipmentItemGroup(METTMSEngineOrderProccessLinesTmp _processLinesTmp, METTMSShipmentOrderIdentifier _tmsShipmentOrderIdentifier, boolean _isToteCustomer, InventLocationId _headerInventLocationId, boolean _hasCCR)
{
    boolean ret;

    TSIGHelper = this.getTSIGHelperInstance(_processLinesTmp, _tmsShipmentOrderIdentifier, _isToteCustomer, _headerInventLocationId, _hasCCR);
    ret = TSIGHelper.create();

    return ret;
}

/// <summary>
/// Step 3a: check if there is an existing shipment this order can be made part of.
/// </summary>
/// <param name = "_shipmentId">Shipment Id will be passed as needed from extension classes</param>
 /// <returns>Instance of <c>METTMSShipmentTable</c></returns>
 protected METTMSShipmentTable initTMSShipment(METTMSShipmentID _shipmentId = shipmentId)
 {
     return METTMSShipmentTable::find(_shipmentId);
 }

/// <summary>
/// Step 3b: If no shipment exists, create a new one
/// </summary>
protected void createTMSShipment()
{
    METTMSShipmentTable tmsShipmentTable;

    this.setTMSShipmentFields(tmsShipmentTable);
    tmsShipmentTable.insert();
}

/// <summary>
/// Method to set the fields for <c>METTMSShipmentTable</c> record
/// </summary>
/// <param name = "_tmsShipmentTable"><c>METTMSShipmentTable</c> record</param>
protected void setTMSShipmentFields(METTMSShipmentTable _tmsShipmentTable)
{
    METRouteStopTable   routeStopTable = METRouteStopTable::findByRouteIdentifier(headerContract.getRouteStopIdentifier());
    METRouteTable       routeTable = METRouteTable::findByRouteIdentifier(headerContract.getRouteIdentifier());

    _tmsShipmentTable.ShipmentID = shipmentId;
    _tmsShipmentTable.SourceWarehouse = headerContract.parmSourceRecord().InventLocationFrom;
    _tmsShipmentTable.DestinationType = headerContract.getDestinationType();
    _tmsShipmentTable.DestinationCustomer = headerContract.getCustomerAccount();
    _tmsShipmentTable.DestinationWarehouse = '';
    _tmsShipmentTable.Route = headerContract.getRoute();
    _tmsShipmentTable.ConfirmedShipDate  = shippingDate;
    _tmsShipmentTable.TMSSendStatus = METTMSSendStatus::ToBeSent;
    _tmsShipmentTable.ShipmentStatus = METCashShipmentStatus::Active;
    _tmsShipmentTable.RouteStop = int2str(headerContract.getRouteStop());
    _tmsShipmentTable.WarehouseZone = routeStopTable.Zone ? routeStopTable.Zone : routeTable.Zone;
    _tmsShipmentTable.StagingLane = headerContract.getStagingLaneId();
    _tmsShipmentTable.PickupEarliest = this.formatUSDate(shippingDate, routeTable.ReadyTime);
    _tmsShipmentTable.PickupLatest = this.formatUSDate(shippingDate, routeTable.DispatchTime);
    _tmsShipmentTable.DeliveryEarliest = this.formatUSDate(deliveryDate, routeStopTable.TimeWindowStart);
    _tmsShipmentTable.DeliveryLatest = this.formatUSDate(deliveryDate, routeStopTable.TimeWindowEnd);
    _tmsShipmentTable.Carrier = headerContract.getCarrierCode();
    _tmsShipmentTable.SpecialDeliveryInstructions = this.getCustomerInstruction();
    _tmsShipmentTable.FinalisationtId = '';
    _tmsShipmentTable.ChepPalletCount    = 0;
    _tmsShipmentTable.LoscamPalletCount  = 0;
    _tmsShipmentTable.PlainPalletCount   = 0;
}

/// <summary>
/// init Customer instruction
/// </summary>
/// <returns>value for <c>METCustomerInstruction</c></returns>
private METCustomerInstruction getCustomerInstruction()
{
    METWarehouseCarrierCustomerView warehouseCarrierCustomerView;
    TransDate                       today = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());

    select firstonly CustomerInstruction from warehouseCarrierCustomerView
        where warehouseCarrierCustomerView.CustAccount == headerContract.getCustomerAccount()
            && warehouseCarrierCustomerView.InventLocationId == headerContract.parmSourceRecord().InventLocationFrom //BUG - Delivery instructions for the warehouse-customer should be used
            && warehouseCarrierCustomerView.StartDate <= today
            && warehouseCarrierCustomerView.EndDate >= today;

    return warehouseCarrierCustomerView.CustomerInstruction;
}

/// <summary>
/// Step 3c: If a shipment exists, update it
/// </summary>
/// <param name = "_shipmentId">TMS shipment Id</param>
/// <param name = "_updateFinalisationId">Update finalisation id</param>
/// <param name = "_updateActuals">Update actual pallet counts</param>
void updateTMSShipment(METTMSShipmentID _shipmentId, boolean _updateFinalisationId = true, boolean _updateActuals = false)
{
    METTMSShipmentTable         tmsShipmentTable;
    METTMSShipmentOrderTable    tmsShipmentOrderTable;

    // calc sum PalletTotalFootprint for the shipment
    select sum(PalletTotalFootprint) from tmsShipmentOrderTable
            where tmsShipmentOrderTable.ShipmentId == _shipmentId;

    // Create SysDaUpdateObject object
    var uo = new SysDaUpdateObject(tmsShipmentTable);

    // Update setting clause
    this.updateTMSShipmentSettingClause(uo, tmsShipmentOrderTable.PalletTotalFootprint, _updateFinalisationId, _updateActuals);

    // Add where clause
    uo.whereClause(new SysDaEqualsExpression(
                   new SysDaFieldExpression(tmsShipmentTable, fieldStr(METTMSShipmentTable, ShipmentID)),
                   new SysDaValueExpression(_shipmentId)));

    // execute update_recordset
    new SysDaUpdateStatement().update(uo);
}

/// <summary>
/// Update TS setting clause
/// </summary>
/// <param name = "_uo"><c>SysDaUpdateObject</c> instance</param>
/// <param name = "_palletTotalFootprint">Pallet total footprint</param>
/// <param name = "_updateFinalisationId">Update finalisation id</param>
/// <param name = "_updateActuals">Update actual pallet counts</param>
void updateTMSShipmentSettingClause(SysDaUpdateObject _uo, METQty _palletTotalFootprint, boolean _updateFinalisationId, boolean _updateActuals)
{
    _uo.settingClause().add(fieldStr(METTMSShipmentTable, TMSSendStatus), new SysDaValueExpression(METTMSSendStatus::ToBeSent));
    _uo.settingClause().add(fieldStr(METTMSShipmentTable, ShipmentStatus), new SysDaValueExpression(METCashShipmentStatus::Active));
    _uo.settingClause().add(fieldStr(METTMSShipmentTable, PalletLifts), new SysDaValueExpression(_palletTotalFootprint));
}

/// <summary>
/// Step 3d: Create TMS Shipment Order record
/// </summary>
/// <returns>Instance of <c>METTMSShipmentOrderTable</c></returns>
METTMSShipmentOrderTable createTMSShipmentOrder()
{
    METTMSShipmentOrderTable    tmsShipmentOrderTable;

    this.setTMSShipmentOrderFields(tmsShipmentOrderTable);
    tmsShipmentOrderTable.insert();

    return tmsShipmentOrderTable;
}

/// <summary>
/// Method to set the fields for <c>METTMSShipmentOrderTable</c> record
/// </summary>
/// <param name = "_tmsShipmentOrderTable"><c>METTMSShipmentOrderTable</c> record</param>
protected void setTMSShipmentOrderFields(METTMSShipmentOrderTable _tmsShipmentOrderTable)
{
    _tmsShipmentOrderTable.initValue();
    _tmsShipmentOrderTable.ShipmentId = shipmentId;
    _tmsShipmentOrderTable.OrderNumber = headerContract.parmSourceRecord().OrderId;
    _tmsShipmentOrderTable.IsCrossDockOrder = NoYes::No;

    METTMSEngineOrderProccessLinesTmp  linesTmp;
    linesTmp.linkPhysicalTableInstance(proccessLinesTmp);
    SalesOrderedQty caseCountSec;
    // BrokenCaseItemQtySecurity and BrokenCaseItemQtyNonSecurity are sum from temp table
    while select sum(BrokenCasesCountNonSecurity), 
        sum(BrokenCasesCountSecurity), 
        sum(RepackCountNonSecurity), 
        sum(RepackCountSecurity), 
        sum(CaseQty_CaseLines)
        from linesTmp
        group by linesTmp.LineCommodity
    {
        _tmsShipmentOrderTable.BrokenCaseItemQtySecurity += roundUpDec(linesTmp.BrokenCasesCountSecurity, 0);
        _tmsShipmentOrderTable.BrokenCaseItemQtyNonSecurity += roundUpDec(linesTmp.BrokenCasesCountNonSecurity, 0);
        _tmsShipmentOrderTable.RepackCaseCountSecurity += roundUpDec(linesTmp.RepackCountSecurity, 0);//round(linesTmp.RepackCountSecurity,2);  // Commented - Bug - CB624_TMSEngineSOCreation
        _tmsShipmentOrderTable.RepackCaseCountNonSecurity += roundUpDec(linesTmp.RepackCountNonSecurity, 0);//round(linesTmp.RepackCountNonSecurity, 2); // Commented - Bug - CB624_TMSEngineSOCreation

        _tmsShipmentOrderTable.CaseCountShipped += linesTmp.CaseQty_CaseLines + this.getRepackContainersByCommodity(roundUpDec(linesTmp.RepackCountSecurity, 0), roundUpDec(linesTmp.RepackCountNonSecurity, 0));
        //_tmsShipmentOrderTable.CaseCountSecurity = _tmsShipmentOrderTable.RepackCaseCountSecurity;
        _tmsShipmentOrderTable.CaseCountSecurity += roundUp(linesTmp.RepackCountSecurity, 1);
    }
    _tmsShipmentOrderTable.SSCC = '';
    _tmsShipmentOrderTable.XDockWMSUpdateReceived = NoYes::No;
    _tmsShipmentOrderTable.VendorNumber = '';
    _tmsShipmentOrderTable.PickListId = postingIdentifier;
}

/// <summary>
/// RepackContainersByCommodity = sum of (roundUp(RepackCountSecurity) + roundUp(RepackCountNonSecurity)) for all the lines on the order per LineCommodity
/// </summary>
/// <param name = "_repackCountSecurity">Repack count security</param>
/// <param name = "_repackCountNonSecurity">Repack count non security</param>
/// <returns>int <c>Int</c></returns>
protected int getRepackContainersByCommodity(real _repackCountSecurity, real _repackCountNonSecurity)
{
    // Bug - CB624_TMSEngineSOCreation - RounUp Changed to 'O' unit from '1' unit
    //Bug 232041 - changed to 1 instead of 0 as it was showing wrong cases
    return real2int(roundUpDec(_repackCountSecurity, 0) + roundUpDec(_repackCountNonSecurity, 0));
}

/// <summary>
/// Step 6a: Update the order’s “Order weight”
/// Step 6b: Update the order’s “Order volume”
/// Step 6c: Update order’s “Pallet Total footprint”
/// </summary>
void updateTMSShipmentOrder()
{
    METTMSShipmentOrderTable    tmsShipmentOrderTable;
    METTMSShipmentItemGroup     tmsShipmentItemGroup;

    // was an issue with update_recordset when TSIG for TOT and CSE
    while select tmsShipmentOrderTable
           where tmsShipmentOrderTable.ShipmentId == shipmentId
                && tmsShipmentOrderTable.OrderNumber == headerContract.parmSourceRecord().OrderId
    {
        tmsShipmentOrderTable.selectForUpdate(true);

        select sum(Weight), sum(Cube) from tmsShipmentItemGroup
            where tmsShipmentItemGroup.TMSShipmentOrderIdentifier == tmsShipmentOrderTable.TMSShipmentOrderIdentifier
                && (tmsShipmentItemGroup.QuantityUOM == METConstants::unitCSE
                || tmsShipmentItemGroup.QuantityUOM like METConstants::KegQtyUOM
                || tmsShipmentItemGroup.QuantityUOM == METConstants::unitTOT);

        tmsShipmentOrderTable.OrderWeight = tmsShipmentItemGroup.Weight;
        tmsShipmentOrderTable.OrderVolume = tmsShipmentItemGroup.Cube;

        //TSIG PAL record per TSO
        select sum(Quantity) from tmsShipmentItemGroup
            where tmsShipmentItemGroup.TMSShipmentOrderIdentifier == tmsShipmentOrderTable.TMSShipmentOrderIdentifier
                && tmsShipmentItemGroup.QuantityUOM == METConstants::unitPal;

        tmsShipmentOrderTable.PalletTotalFootprint = decRound(tmsShipmentItemGroup.Quantity,2); //tmsShipmentItemGroup.Quantity; //  Commented - Bug - CB624_TMSEngineSOCreation

        tmsShipmentOrderTable.update();
    }

}

