/// <summary>
/// TMS needs US date format, concatenate date and time(str)
/// </summary>
/// <param name = "_date">TMS delivery or shipping date</param>
/// <param name = "_time">Route or route stop time format HHmm</param>
/// <returns>Formatted date and time in US format mm/dd/yyyy hh:mm</returns>
METDelivery formatUSDate(TransDate _date, METRouteTime _time)
{
    // Bug - CB624_TMSEngineSOCreation
    METRouteTime time = _time == METConstants::emptyString ? METConstants::strTimeHHmm : _time;

    return strFmt(METConstants::value1SpaceValue2, date2Str(_date, 213, DateDay::Digits2, DateSeparator::Slash, DateMonth::Digits2, DateSeparator::Slash, DateYear::Digits4), strIns(time, METConstants::colon, 3));
}

